import{_ as t,o,c as d,a2 as a}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"开发与验证","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/testing/feedback-loop","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"testing/feedback-loop.md","filePath":"testing/feedback-loop.md"}'),c={name:"testing/feedback-loop.md"};function r(n,e,p,i,l,s){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="开发与验证" tabindex="-1">开发与验证 <a class="header-anchor" href="#开发与验证" aria-label="Permalink to &quot;开发与验证&quot;">​</a></h1><p>目标：为自己的 Lab Word 变更选择能观察结果的公开检查。命令从仓库根目录执行，完整职责见<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/testing/strategy.md" target="_blank" rel="noreferrer">测试策略</a>。</p><h2 id="选择入口" tabindex="-1">选择入口 <a class="header-anchor" href="#选择入口" aria-label="Permalink to &quot;选择入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变更</th><th>命令</th><th>观察结果与前提</th></tr></thead><tbody><tr><td>Web 行为</td><td><code>pnpm test:frontend</code></td><td>真实组件操作；HTTP 使用 MSW；motion golden 需 Python 3</td></tr><tr><td>TypeScript 与边界</td><td><code>pnpm typecheck</code>、<code>pnpm boundaries:check</code></td><td>类型、包依赖、Node 模块、限定表与 SDK 归属</td></tr><tr><td>后端行为</td><td><code>pnpm test:server</code></td><td>真实 Node HTTP/CLI 与隔离嵌入数据</td></tr><tr><td>合同</td><td><code>pnpm generate</code>、<code>pnpm contracts:check</code></td><td>Node OpenAPI、正式生成类型与 SDK 一致</td></tr><tr><td>文档</td><td><code>pnpm docs:check</code>、<code>pnpm docs:build</code></td><td>来源、双语、Node 生成参考与构建链接</td></tr><tr><td>文档浏览器旅程</td><td><code>pnpm test:e2e:docs</code></td><td>语言、主题、搜索、约定视口与自定义 base；需 Chromium</td></tr><tr><td>应用关键旅程</td><td><code>pnpm test:e2e</code></td><td>所属 Node/Web 与真实 Chromium/WebGL；motion smoke 需固定 Python 环境</td></tr></tbody></table><p>首次浏览器验证执行 <code>pnpm exec playwright install chromium</code>。默认 <code>pnpm test:e2e</code> 还需要独立 Python 环境，按<a href="./../tutorials/synthetic-motion#启动-python-publisher">合成运动教程</a>安装 tracked requirements 的固定版本。运行器默认读取 <code>.scratch/motion-python/bin/python</code>，也可用 <code>MOTION_E2E_PYTHON</code> 指定解释器路径。</p><p>默认 suite 执行 motion smoke，不执行至少 600 秒的完整运动验收。完整命令与两者覆盖范围见<a href="./../tutorials/synthetic-motion#验证源码">验证源码</a>。<code>pnpm check</code> 包含当前 Node、格式、静态、行为、性能预算与构建检查，不含浏览器 E2E；其中 TS/Python golden 检查需要 Python 3，可用 <code>PYTHON</code> 指定解释器。正常 Node/Web 启动与构建不需要 Python。</p><p>命令能力不扩大任务范围。默认验证 desktop web；移动适配、窄屏、触屏或真机只按明确批准的范围加入。heavy browser 前先核对 discovery 与前提；已有关键旅程复用，CSS/布局变更选择受影响的 focused case。</p><p><code>docs:check</code> 与 <code>docs:build</code> 读取正式 Node OpenAPI 和当前配置解析器。<code>pnpm test:e2e</code> 使用所属 Linux Node/Web 浏览器监督入口。当前 CI 执行 <code>pnpm check</code>，先检查静态、完整前端和工具，再运行长服务与合同套件。明确实际浏览器前提与任务范围。</p><h2 id="lab-viewer-的实际边界" tabindex="-1">Lab Viewer 的实际边界 <a class="header-anchor" href="#lab-viewer-的实际边界" aria-label="Permalink to &quot;Lab Viewer 的实际边界&quot;">​</a></h2><p>正式 Viewer 与持久 World 沿用已接受的 <a href="./../guides/lab-viewer">Lab 体验</a>。保留浏览器旅程验证真实 GLB/HDR/WebGL、选择、草稿、设备和恢复。</p><p>正式接入时，组件测试观察导入控件、选择、loading/error 与恢复，浏览器观察真实 GLB/HDR、画布像素、相机和资源释放。DOM 成功不能证明三维模型可见；一次内存采样不能证明泄漏。</p><p>首次进入含模型的 World 或资产查看器时，浏览器检查通过 <code>expectInitialSceneReady</code> 最多等待 15 秒，并继续检查实际模型、像素与错误状态。<a href="https://github.com/CaiZongyuan/labworld/actions/runs/38074047499" target="_blank" rel="noreferrer">实际 GitHub Ubuntu/SwiftShader 诊断</a> 在 9.269 秒观察到正确的 20 模型场景；原 5 秒失败仍保留。这个测试环境等待只用于初始场景，不改变产品性能承诺、后续操作或恢复等待、600 秒运动验收及计数预算。</p><h2 id="失败与证据" tabindex="-1">失败与证据 <a class="header-anchor" href="#失败与证据" aria-label="Permalink to &quot;失败与证据&quot;">​</a></h2><p>如果 Docker、Chromium 或依赖缺失，记录命令、失败条件和未验证范围，不把跳过视为通过。后端检查使用隔离资源，不清理开发或生产数据。</p><p>在固定的源码版本、环境和任务范围上记录验证。真实 TDD red/green可复用为同一断言的 VDD 证据。稳定最终候选由本地定向检查与负责环境的一次完整门禁覆盖；已包含的 affected 检查不重复运行。修复和 main 前进按语义影响刷新，具体顺序与独立审查见<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/agents/development-flow.md" target="_blank" rel="noreferrer">开发流程</a>。</p><p>多阶段协作使用 <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/.agents/skills/development-timeline/SKILL.md" target="_blank" rel="noreferrer">development-timeline</a>轻量记录阶段、等待和返工。报告说明已记录的进展与未知部分，不追加产品验证或合并门禁。</p><hr><p>源码版本：<code>c80e63c8c063</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/testing/t01-feedback-loop.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',18)])])}const m=t(c,[["render",r]]);export{b as __pageData,m as default};
